# פרק 9 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=9
TITLE='לשון הרע'
SUM=[' <p>מוסדרת בחוק נפרד — <strong>חוק איסור לשון הרע, התשכ"ה–1965</strong> — ומאזנת בין השם הטוב לחופש הביטוי.</p> <h3>9.1 מהי לשון הרע — סעיף 1</h3> <p>דבר שפרסומו עלול <strong>להשפיל</strong> אדם בעיני הבריות, <strong>לבזותו</strong>, לפגוע במשרתו/עסקו/מקצועו, או לעשותו מטרה לשנאה, בוז או לעג. נבחן לפי המשמעות ה<strong>אובייקטיבית</strong>.</p> <h3>9.2 פרסום — סעיף 2</h3> <p>הבעה בכל אמצעי שהגיעה ל<strong>אדם אחד לפחות זולת הנפגע</strong> (בכתב — גם אם הייתה עשויה להגיע).</p> <h3>9.3 ההגנות המרכזיות</h3> <p><strong>אמת בפרסום</strong> (<strong>סעיף 14</strong>) — הפרסום אמת ויש בו <strong>עניין ציבורי</strong>. <strong>תום לב</strong> (<strong>סעיף 15</strong>) — מגוון נסיבות (חובה חוקית/מוסרית, הבעת דעה, ביקורת) שבהן פרסום בתום לב מוגן.</p> <h3>9.4 פיצוי ללא הוכחת נזק — סעיף 7א</h3> <p>ניתן לפסוק פיצוי ללא הוכחת נזק (עד תקרה, וכפולה בפרסום שנעשה בכוונה לפגוע).</p> <h3>9.5 נקודות מפתח למבחן</h3> <ul><li>הגדרה אובייקטיבית (ס׳ 1); פרסום לאדם אחד נוסף (ס׳ 2).</li><li>הגנות: אמת + עניין ציבורי (14), תום לב (15).</li><li>פיצוי ללא הוכחת נזק (ס׳ 7א).</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[('חוק איסור לשון הרע, התשכ"ה-1965 (ס׳ 1-2)', '', 'הגדרת לשון הרע (מבחן אובייקטיבי) ו"פרסום" — הגעה לאדם אחד לפחות זולת הנפגע.'), ("ס' 14-15 — הגנות", '', 'אמת בפרסום בעניין ציבורי (ס׳ 14) ותום לב על נסיבותיו (ס׳ 15) — נקודת האיזון מול חופש הביטוי.'), ("ס' 7א — פיצוי ללא הוכחת נזק", '', 'בית המשפט רשאי לפסוק פיצוי ללא הוכחת נזק (עד תקרה, וכפול בפרסום שנעשה בכוונה לפגוע).'), ('ד״נ 9/77 חברת החשמל לישראל בע״מ נ׳ הוצאת עיתון ״הארץ״ בע״מ', '״הארץ״ פרסם שמכירת מכונית פאר שרכשה חברת החשמל למנהלה הכללי, לאחר ביקורת ציבורית, היא מכירה למראית עין. בע״א 723/74 קיבל ביהמ״ש העליון את ערעור העיתון, ובדיון הנוסף נבחנה ההכרעה מחדש.', 'ברוב דעות הוחזר פסק הדין לטובת חברת החשמל. נקבע שחופש הביטוי אינו עדיף על הזכות לשם טוב (בניגוד לגישת New York Times v. Sullivan), והאיזון הוא זה שבחוק. כדי ליהנות מהגנת הבעת הדעה לפי ס׳ 15(4) יש להפריד בבירור בין עובדות לדעה, ומי שמערבב ביניהן מאבד את ההגנה.'), ('ע״א 214/89 אבנרי נ׳ שפירא', 'דיון בבקשה למנוע מראש פרסום שנטען שיש בו לשון הרע, בשאלת היחס בין הזכות לשם טוב לבין חופש הביטוי.', 'נקבע שביהמ״ש יימנע ככלל ממניעה מוקדמת של פרסום בטענת לשון הרע, בייחוד כשהמפרסם מעלה הגנה של אמת או תום לב שאינה נראית בדויה. בפסק הדין הודגשה גם חשיבות השם הטוב כזכות יסוד, ובהמשך נאמר (בפרשת אמר) שהצד השני של ההלכה הוא שהמפרסם נושא במלוא ההשלכות אם יתברר שפרסם לשון הרע.'), ('דנ״א 7325/95 ידיעות אחרונות בע״מ נ׳ קראוס', 'דיון נוסף שעסק בהגנות העומדות לעיתון שפרסם ידיעות על אדם, ובהיקף חופש העיתונות.', 'פסק הדין הוא המקור לגישת ״אמת לשעתה״: אמיתות הפרסום נבחנת לפי התמונה שהציג ביחס למה שהיה ידוע בזמן הפרסום. בערעור בפרשת דיין הסתמכו עליו שניים משופטי ההרכב; בדיון הנוסף בפרשת דיין הודגש שבהגנת האמת על המפרסם להוכיח שהדברים אמת, וההגנה על עיתונות אחראית הוכרה דווקא במסגרת ס׳ 15(2), תוך שינוי ״הלכת הארץ״.'), ('רע״א 4740/00 אמר נ׳ יוסף', 'עיתון פרסם על תינוקת שנולדה עם מומים ונעזבה בבית החולים, ובכותרת המשנה נכתב שאמה מכורה לסמים. ביהמ״ש השלום פסק 100,000 ש״ח, והמחוזי הפחית ל־40,000.', 'ביהמ״ש העליון החזיר את הפיצוי המלא. נקבע שהוכח נזק לא ממוני — פגיעה בשם ופגיעה קשה ברגשות — ושהמפרסמים הגדילו את הנזק כשלא תיקנו והמשיכו לטעון לאמיתות. עוד נקבע שס׳ 7א(ב) אינו קובע תקרה לפיצוי, אלא מאפשר פיצוי בלי הוכחת נזק.'), ('דנ״א 2121/12 פלוני נ׳ ד״ר אילנה דיין־אורבך', 'תחקיר ״עובדה״ על אירוע ״וידוא ההריגה״ ברפיח הציג את מפקד הפלוגה באור פוגע. המפקד זוכה בבית הדין הצבאי ותבע את העיתונאית ואת הזכיינית. בערעור פוטרה העיתונאית, והוגשה בקשה לדיון נוסף.', 'בהרכב של תשעה נקבע שבהגנת האמת על המפרסם להוכיח שהדברים אמת. במסגרת ס׳ 15(2) הוכרה חובה לפרסם עניינים בעלי עניין ציבורי משמעותי — בתום לב ולפי אמות מידה מחמירות של עיתונות אחראית. אין חובה כללית לפרסם עדכון כשלא התבקש. התחקיר הוגן; הפרומואים לא.'), ('רע״א 4447/07 מור נ׳ ברק אי.טי.סי. [1995] החברה לשירותי בזק בינלאומיים בע״מ', 'דיון בבקשה לחייב ספק שירותי אינטרנט לחשוף את זהותו של מי שפרסם ברשת, באופן אנונימי, דברים שנטען שהם לשון הרע.', 'פסק דין מוביל בשאלת חשיפת זהותו של מפרסם אנונימי ברשת, שאיזן בין הזכות לשם טוב לבין חופש הביטוי והזכות לפרטיות של הגולשים. ביהמ״ש העליון הכריע שבהיעדר הסדר חקיקתי מתאים לא ניתן לחייב את הספק לחשוף את הזהות, והפנה את הסוגיה למחוקק.')]
QS=[{'q': 'מהו המבחן לקביעת משמעותו של פרסום בתביעת לשון הרע?', 'o': ['הדרך שבה האדם הסביר מהציבור הרלוונטי יבין את הפרסום, כמכלול', 'המשמעות המילונית של כל מילה בנפרד', 'כוונתו הסובייקטיבית של המפרסם', 'הדרך שבה התובע עצמו הבין את הפרסום'], 'c': 0, 'e': 'נכון. בוחנים את הפרסום כולו, כולל הקשר ורמזים, לפי הבנת הקורא או השומע הסביר.'}, {'q': 'מה ההבדל בין העוולה האזרחית לבין העבירה הפלילית לפי חוק איסור לשון הרע?', 'o': ['העבירה חלה רק על עיתונים', 'העוולה דורשת כוונה לפגוע והעבירה לא', 'העוולה דורשת פרסום לאדם אחד לפחות זולת הנפגע, בלי כוונה לפגוע; העבירה — לשניים לפחות ובכוונה לפגוע', 'אין הבדל ביסודות'], 'c': 2, 'e': 'נכון. ס׳ 7 — אדם אחד או יותר; ס׳ 6 — שני בני אדם או יותר ובכוונה לפגוע.'}, {'q': 'עובד צעק על מנהלו בחדר סגור, כששניהם לבד: ״אתה גנב!״. האם יש עוולת לשון הרע?', 'o': ['כן, אבל רק עבירה פלילית', 'לא, כי לא היה פרסום לאדם זולת הנפגע', 'כן, כי נאמר דבר משפיל', 'לא, כי מנהל אינו ״אדם״ לפי החוק'], 'c': 1, 'e': 'נכון. ס׳ 7 דורש פרסום ״לאדם אחד או יותר זולת הנפגע״.'}, {'q': 'כתב מאמר: ״כל השמאים בעיר הם רמאים״. שמאי מהעיר מבקש לתבוע. מה הדין, בהנחה שבעיר מאות שמאים?', 'o': ['יכול לתבוע, כי הוא שמאי בעיר', 'אינו יכול לתבוע, כי לשון הרע על ציבור שאינו תאגיד אינה מקימה עילה אזרחית, והפרסום אינו מזהה אותו אישית', 'יכול לתבוע רק בקובלנה', 'יכול לתבוע רק אם יוכיח נזק כספי'], 'c': 1, 'e': 'נכון. ס׳ 4 שולל עילה אזרחית וקובלנה; רק בקבוצה קטנה ומזוהה ייתכן שהפרסום מתייחס לכל חבר.'}, {'q': 'מה קובע ס׳ 14 לחוק?', 'o': ['שעל התובע להוכיח שהפרסום שקרי', 'שאמת היא תמיד הגנה מלאה', 'שעיתונאי פטור אם פרסם בתום לב', 'שהגנה טובה היא שהדבר שפורסם היה אמת והיה בפרסום עניין ציבורי; ושההגנה לא תישלל רק בשל פרט לוואי שלא הוכח ושאין בו פגיעה של ממש'], 'c': 3, 'e': 'נכון. זו לשון ס׳ 14 — שני תנאים מצטברים ופטור לפרט לוואי.'}, {'q': 'עיתון פרסם כי ״הרופא ד׳ הורשע בהונאה בשנת 2015 ונידון לשנה מאסר״. בפועל הורשע בהונאה, אך נידון לעשרה חודשים. האם ההגנה לפי ס׳ 14 נשללת?', 'o': ['לא, כי ס׳ 14 אינו דורש אמת', 'כן, כי עניין ציבורי לא קיים לגבי רופאים', 'לא — אורך העונש הוא פרט לוואי שאין בו פגיעה של ממש, וגרעין הפרסום אמת', 'כן, כל אי־דיוק שולל את ההגנה'], 'c': 2, 'e': 'נכון. הגרעין המשמיץ — הרשעה בהונאה — אמת, וההבדל בעונש אינו מוסיף פגיעה ממשית.'}, {'q': 'בלוגר פרסם פרטים נכונים לחלוטין על מחלה של שכנו, אדם פרטי שאינו איש ציבור, בלי כל תועלת ציבורית. האם עומדת לו הגנת ס׳ 14?', 'o': ['כן, אם התנצל', 'לא, כי מחלה אינה יכולה להיות לשון הרע', 'לא, כי אין בפרסום עניין ציבורי — ואף ייתכן שהוא פוגע בפרטיות', 'כן, כי הדברים אמת'], 'c': 2, 'e': 'נכון. עניין ציבורי הוא תנאי מצטבר, ופרסום כזה עלול גם להוות פגיעה בפרטיות.'}, {'q': 'לקוח התלונן לנציבות מוסמכת על התנהגות של עובד ציבור, וטעה בתום לב באחד הפרטים. איזו הגנה מתאימה?', 'o': ['ס׳ 15(8) — תלונה לרשות המוסמכת, בתום לב', 'אין הגנה, כי נפלה טעות', 'ס׳ 14 — אמת', 'ס׳ 13(5) — הליך שיפוטי'], 'c': 0, 'e': 'נכון. ס׳ 15(8) מגן על תלונה לרשות מוסמכת, גם בלי להוכיח אמת, בכפוף לתום לב ולתחום הסביר.'}, {'q': 'אותו לקוח העלה את נוסח התלונה גם לפייסבוק, לכלל הציבור. האם ההגנה של ס׳ 15(8) חלה גם על הפוסט?', 'o': ['כן, אם הפוסט זהה לתלונה', 'כן, כל פרסום של תלונה מוגן', 'לא, כי פייסבוק אינו ״פרסום״', 'לא — ס׳ 15(8) מסייג במפורש שאין בו הגנה על פרסום אחר של התלונה, של דבר הגשתה או של תוכנה'], 'c': 3, 'e': 'נכון. זו לשון הסייג בס׳ 15(8); הפוסט ייבחן לפי הגנות אחרות, אם בכלל.'}, {'q': 'מה קבע ביהמ״ש העליון בדיון הנוסף בפרשת חברת החשמל נ׳ הארץ לגבי הגנת הבעת הדעה (ס׳ 15(4))?', 'o': ['שהגנה זו חלה רק על עיתונאים', 'שכל ביקורת על גוף ציבורי מוגנת', 'שיש להפריד בבירור בין עובדות לבין דעה, כדי שהקורא יוכל לשפוט בעצמו; ערבוב שולל את ההגנה', 'שדעה חייבת להיות מנומסת'], 'c': 2, 'e': 'נכון. זו הדרישה שנקבעה בד״נ 9/77, והעיתון לא עמד בה.'}, {'q': 'מה קובע ס׳ 16(ב)(2)?', 'o': ['שעיתונאי חייב לפרסם תגובה', 'שחזקה על הנתבע שפעל בתום לב אם פרסם לקהל קטן', 'שחזקה על הנתבע שפעל שלא בתום לב אם הדבר לא היה אמת והוא לא נקט לפני הפרסום אמצעים סבירים לבדוק אם הוא אמת', 'שעל התובע להוכיח כוונה לפגוע'], 'c': 2, 'e': 'נכון. זו החזקה שמענישה פרסום בלי בדיקה סבירה.'}, {'q': 'מה ההלכה שנקבעה בדיון הנוסף בפרשת דיין לגבי עיתונות?', 'o': ['שבמסגרת ס׳ 15(2) מוכרת חובה לפרסם עניינים בעלי עניין ציבורי משמעותי, בתום לב ולפי אמות מידה מחמירות של עיתונות אחראית', 'שהגנת האמת אינה חלה על תחקירי טלוויזיה', 'שעיתונאי חייב תמיד לפרסם עדכון גם בלי בקשה', 'שלעיתונות יש חסינות מוחלטת'], 'c': 0, 'e': 'נכון. זו ההכרה ב״עיתונות אחראית״ בתוך ס׳ 15(2).'}, {'q': 'מה קבע ביהמ״ש העליון בפרשת אמר נ׳ יוסף לגבי ס׳ 7א(ב)?', 'o': ['שפיצוי בלי הוכחת נזק אפשרי רק לתאגיד', 'שהסעיף חל רק בהליך פלילי', 'שהסעיף מאפשר פיצוי בלי הוכחת נזק, אבל אינו תקרה — ניתן לפסוק יותר כשהנזק מוכח', 'שזו תקרה לכל פיצוי בלשון הרע'], 'c': 2, 'e': 'נכון. בפרשה הוחזר פיצוי של 100,000 ש״ח, שעלה על הסכום הנקוב בס׳ 7א(ב).'}, {'q': 'הוכח שנתבע פרסם לשון הרע בכוונה לפגוע. מה הסכום המרבי שביהמ״ש רשאי לפסוק בלי הוכחת נזק?', 'o': ['פי עשרה מהסכום הבסיסי', 'כפל הסכום שבס׳ 7א(ב), כשהסכומים צמודים למדד', 'אין אפשרות לפיצוי בלי הוכחת נזק', '50,000 ש״ח בדיוק'], 'c': 1, 'e': 'נכון. ס׳ 7א(ג) מתיר עד כפל הסכום, והסכומים מתעדכנים לפי ס׳ 7א(ה).'}, {'q': 'אדם מבקש מביהמ״ש צו מניעה זמני נגד פרסום ספר שלטענתו משמיץ אותו. המחבר טוען שהדברים אמת ומציג ראיות לכאורה. מה הסיכוי?', 'o': ['גבוה — כל טענה ללשון הרע מצדיקה צו', 'נמוך — לפי הלכת אבנרי נ׳ שפירא, ביהמ״ש נמנע ככלל ממניעה מוקדמת של פרסום, בייחוד כשמועלית הגנה שאינה נראית בדויה', 'גבוה — אם התובע הוא איש ציבור', 'אין לביהמ״ש סמכות לתת צווים בלשון הרע'], 'c': 1, 'e': 'נכון. זו הלכת אבנרי; הנפגע יכול לתבוע פיצוי בדיעבד.'}, {'q': 'מה מהבאים הוא ״פרסום מותר״ לפי ס׳ 13 (חסינות מוחלטת)?', 'o': ['דברים שאמר עד במהלך עדותו בבית המשפט', 'פוסט של עורך דין בפייסבוק על הצד שכנגד', 'ראיון של בעל דין לעיתון אחרי הדיון', 'מכתב התראה ששלח עורך דין לפני הגשת תביעה'], 'c': 0, 'e': 'נכון. ס׳ 13(5) מגן על פרסום של עד ״שנעשה תוך כדי דיון״.'}, {'q': 'עיתון סירב לפרסם תיקון שדרש הנפגע בכתב, בהתאם לתנאי ס׳ 17. מה התוצאה לגבי עורך העיתון?', 'o': ['אין לכך משמעות', 'הוא חייב לפרסם תיקון ב״ידיעות״ בנוסף', 'הוא יהיה אחראי פלילית באופן אוטומטי', 'לא תעמוד לו הגנת תום הלב לפי ס׳ 15'], 'c': 3, 'e': 'נכון. ס׳ 17(א) שולל את הגנת תום הלב מהעורך, ממי שהחליט על הפרסום ומהאחראי לאמצעי התקשורת.'}, {'q': 'פלוני שיתף ברשת פוסט שהעלה אחר, ובו לשון הרע על אלמוני, בלי להוסיף דבר. מה הגישה הנכונה?', 'o': ['המשתף אחראי רק אם הוא עיתונאי', 'רק כותב הפוסט המקורי אחראי, תמיד', 'שיתוף לעולם אינו פרסום', 'שיתוף עשוי להיחשב פרסום חדש, ויש לבחון את ההגנות לגבי המשתף; ״רק שיתפתי״ אינה הגנה כשלעצמה'], 'c': 3, 'e': 'נכון. השיתוף מפיץ את הדברים לקהל נוסף; ההגנות נבחנות לגבי המשתף, ואזכור המקור הוא לכל היותר הקלה (ס׳ 19(1)).'}, {'q': 'מה מבטאת הלכת ד״נ 9/77 לגבי היחס בין חופש הביטוי לזכות לשם טוב?', 'o': ['שהשם הטוב גובר תמיד', 'שחופש הביטוי גובר תמיד, כמו בפרשת New York Times v. Sullivan', 'שאין לפרסם ביקורת על חברות ממשלתיות', 'שאף זכות אינה עליונה על רעותה, והאיזון הוא זה שקבע המחוקק בחוק איסור לשון הרע'], 'c': 3, 'e': 'נכון. זו ההלכה שנקבעה בדיון הנוסף בפרשת הארץ.'}, {'q': 'עיתון פרסם שנפתחה חקירה נגד אדם; בהמשך התיק נסגר. האדם דרש בכתב לפרסם את סגירת התיק, והעיתון סירב. מה הדין?', 'o': ['העיתון חייב לפרסם את ההחלטה העדכנית בהבלטה ראויה ובזמן סביר; הפרת החובה היא עוולה אזרחית (ס׳ 25א)', 'אין חובה, כי הידיעה המקורית הייתה אמת', 'רק ביהמ״ש יכול להורות על כך, בהליך פלילי', 'החובה חלה רק אם הוגש כתב אישום'], 'c': 0, 'e': 'נכון. זו חובת העדכון שבס׳ 25א, וס׳ 25א(ג) הופך את הפרתה לעוולה אזרחית.'}, {'q': 'מבחן "לשון הרע" (ס\' 1) הוא:', 'o': ['סובייקטיבי', 'אובייקטיבי', 'כלכלי', 'פלילי'], 'c': 1, 'e': 'איך הפרסום נתפס.'}, {'q': 'מהו "פרסום" (ס\' 2)?', 'o': ['רק בעיתון', 'הגעה לאדם אחד לפחות זולת הנפגע', 'רק בכתב', 'רק לנפגע'], 'c': 1, 'e': 'די באדם אחד נוסף.'}, {'q': 'הגנת "אמת בפרסום" (ס\' 14) דורשת:', 'o': ['אמת בלבד', 'אמת + עניין ציבורי', 'תום לב', 'הסכמה'], 'c': 1, 'e': 'שני תנאים מצטברים.'}, {'q': 'הגנת תום הלב מעוגנת ב:', 'o': ["ס' 14", "ס' 15", "ס' 7א", "ס' 1"], 'c': 1, 'e': 'מגוון נסיבות מוגנות.'}, {'q': "מה מאפשר ס' 7א?", 'o': ['מאסר', 'פיצוי ללא הוכחת נזק', 'חנינה', 'ביטול הפרסום'], 'c': 1, 'e': 'עד תקרה, כפול בכוונה לפגוע.'}]
